 pts.push([0,0,0],[Rf,0,0],[0,Rf,0],[Rf*0.7071,Rf*0.7071,0],[-78,-66,0],[-70,-58,0],[-12,-58,0],[-70,-14,0],[-12,-30,H+8],[R,0,H+8],[0,R,H+8]);
