 for(i=1;i<n;i++){var dx=pts[i][0]-pts[i-1][0],dy=pts[i][1]-pts[i-1][1],l=Math.abs(dx)+Math.abs(dy);dirs.push([Math.sign(dx),Math.sign(dy)]);lens.push(l)}
