 return '<g class="'+K+'__lens"><circle class="'+K+'__lens-rim" cx="'+cx+'" cy="'+cy+'" r="'+(r+6)+'"/><circle class="'+K+'__lens-face" cx="'+cx+'" cy="'+cy+'" r="'+r+'"/>'
